// Canned but topic-matched analyst Q&A — simulates a lightweight retrieval
// system referencing the active incident's event/alert/MITRE context.
export function answerAnalystQuestion(question: string, incidentId: string): string {
  const q = question.toLowerCase()
  const a = AI_ANALYSES[incidentId]
  if (!a) return 'No active incident context is loaded. Select an incident to begin analysis.'

  if (q.includes('what happened')) {
    return `${a.affectedAsset} (${a.affectedAssetIp}) was targeted by activity classified as ${a.attackPattern} (${a.mitreId} - ${a.mitreName}). ${a.narrative}`
  }
  if (q.includes('why') && q.includes('critical')) {
    return `This incident is rated ${a.risk}/100 because it targets a high-value asset (${a.affectedAsset}), involves a privileged account, and matches a high-confidence detection pattern (${a.confidence}% confidence) for ${a.mitreName}. Left unaddressed, techniques like this frequently precede lateral movement or full domain compromise.`
  }
  if (q.includes('investigate') || q.includes('next')) {
    return `Recommended next steps:\n${a.recommendedActions.map((r, i) => `${i + 1}. ${r}`).join('\n')}`
  }
  if (q.includes('evidence')) {
    return `Key evidence supporting this classification:\n• Source: ${a.source}\n• Target: ${a.affectedAsset} (${a.affectedAssetIp})\n• MITRE Technique: ${a.mitreId} — ${a.mitreName}\n• Detection confidence: ${a.confidence}%\n• Risk score: ${a.risk}/100`
  }
  if (q.includes('mitre') || q.includes('technique')) {
    return `${a.mitreId} — ${a.mitreName} falls under the ${a.threatType} category of the MITRE ATT&CK framework. This technique was mapped based on observed behavioral indicators including timing patterns, process lineage, and target selection consistent with known adversary tradecraft for this technique.`
  }
  return `Based on current incident context: ${a.narrative}`
}

export const SUGGESTED_QUESTIONS = [
  'What happened?',
  'Why is this critical?',
  'What should I investigate next?',
  'Show evidence',
  'Explain the MITRE technique',
]

export function initialChatForIncident(incidentId: string): ChatMessage[] {
  const a = AI_ANALYSES[incidentId]
  if (!a) return []
  return [
    {
      id: 'sys-1',
      role: 'ai',
      content: `Incident context loaded: ${incidentId}. Ready to assist with investigation. Ask a question or use a quick action above.`,
      timestamp: new Date().toISOString(),
    },
  ]
}
